namespace ks{namespace{PartSignalPartialTest partialTest=nullptr;using T=PartSignalTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){bool status=t.kind()==K::Status;switch(t.stage()){case S::Mask:return{t.kind()==K::Start?0xa182u:t.kind()==K::Continue?0xa188u:0xa18eu,4};case S::Join:return{t.kind()==K::Start?0xa186u:t.kind()==K::Continue?0xa18cu:0xa192u,2};case S::ReadPart:return{status?0xa106u:0xa194u,6};case S::ReadBase:return{status?0xa10cu:0xa19au,6};case S::Difference:return{status?0xa112u:0xa1a0u,2};case S::Admit:return{status?0xa114u:0xa1a2u,2};case S::Clamp:return{status?0xa116u:0xa1a4u,2};case S::ClearHigh:return{0xa118,2};case S::Offset:return{status?0xa11au:0xa1a6u,4};case S::AddOffset:return{0xa11e,2};case S::SetValue:return{0xa120,6};case S::Dispatch:return{status?0xa126u:0xa1aau,4};case S::AwaitPacket:case S::Finish:return{status?0xa12au:0xa1aeu,2};default:throw std::runtime_error("Invalid part signal stage");}}}
bool PartSignalCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token==h.getSP()){selected=&c;break;}if(pc==0xa106||pc==0xa182||pc==0xa188||pc==0xa18e){if(selected)throw std::runtime_error("Overlapping native part signal");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Part signal capacity");selected->emplace(pc==0xa106?K::Status:pc==0xa182?K::Start:pc==0xa188?K::Continue:K::Stop,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;if(t.awaiting())t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return uint8_t(h.read8(r==T::Read::Part?0x17526:0x167ba));});auto&v=h.regs;auto&part=t.kind()==K::Status?v[1].rl:v[1].rh;switch(stage){case S::Mask:f.move(v[1].e,t.mask());break;case S::ReadPart:f.move(part,t.part());break;case S::ReadBase:f.move(v[0].rl,t.base());break;case S::Difference:part=h.sub8(part,v[0].rl);break;case S::Clamp:f.move(part,0);break;case S::ClearHigh:f.move(v[1].rh,0);break;case S::Offset:f.move(v[4].r,t.kind()==K::Status?0x8041:0x8040);break;case S::AddOffset:v[4].r=h.add16(v[4].r,v[1].r);break;case S::SetValue:f.move(v[1].er,0x100);break;case S::Dispatch:if(uint16_t(v[4].r)!=t.address()||(uint32_t(v[1].er)>>8)!=t.wire())throw std::runtime_error("Part signal packet differs");f.call(0x24c6);h.pc=h.makepc(f.next);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Dispatch&&stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Part signal clocks differ");return true;}}

